target.command:
cd /home/john/mynotes/deterministic_equidistribution_theory/c_suite/out_large
awk -F, '
  FNR==NR { if(!/^#/ && $1!="Q") { g0[$1","$2]=$5; g1[$1","$2]=$6 } ; next }
  !/^#/ && $1!="window_id" && NF>=14 && $14==1 {
    Q=$7;k=$8;s=$9;W=$6;L=$4; key=Q","k; gap=-1;
    if(s=="1.0000")gap=g1[key]; else if(s=="0.0000")gap=g0[key];
    if(gap>=0){ n++; sx+=W;sy+=gap;sxy+=W*gap;sx2+=W*W;sy2+=gap*gap;
                if(L>=64){ln++; lsy+=gap} } }
  END{ corr=(n*sxy-sx*sy)/sqrt((n*sx2-sx*sx)*(n*sy2-sy*sy));
    printf "joined shadows=%d  mean|W|=%.4f  mean gap_ratio=%.4f  corr(|W|,gap)=%.3f\n",n,sx/n,sy/n,corr;
    printf "long(>=64): n=%d  mean gap_ratio=%.4f\n",ln,ln?lsy/ln:0 }
' fourier_comparison.csv shadow_search.csv
